const input = $input.first().json;
const body = input.body || input;
const projectId = body.project_id;
const reportType = body.report_type || null;
const forceRefresh = body.force_refresh || false;

if (!projectId) throw new Error('project_id is required');

return [{
  json: {
    project_id: projectId,
    report_type: reportType,
    force_refresh: forceRefresh,
    started_at: new Date().toISOString()
  }
}];

const crypto = require('crypto');
const docs = $input.first().json;
const docsArray = Array.isArray(docs) ? docs : [docs];
const hashes = docsArray.map(d => d.content_hash).filter(Boolean).sort();
const evidenceHash = crypto.createHash('sha256').update(hashes.join('|'), 'utf-8').digest('hex');
const prevData = $('Extract Input').first().json;

return [{
  json: {
    ...prevData,
    evidence_hash: evidenceHash,
    indexed_docs_count: hashes.length
  }
}];

const cached = $('Check Cache').first().json[0];
const meta = $('Build Evidence Hash').first().json;

return [{
  json: {
    status: 'cache_hit',
    project_id: meta.project_id,
    report_type: meta.report_type,
    evidence_hash: meta.evidence_hash,
    html_content: cached.html_content,
    md_content: cached.md_content,
    json_output: cached.json_output,
    source: 'cache'
  }
}];

const results = $input.first().json;
const resultsArray = Array.isArray(results) ? results : [results];
const meta = $('Build Evidence Hash').first().json;

const sections = {};
for (const r of resultsArray) {
  if (!r.finding_key) continue;
  sections[r.finding_key] = {
    data: r.structured_data,
    confidence: r.confidence_score,
    evidence: r.evidence_refs,
    version: r.version,
    skill: r.source_skill
  };
}

return [{
  json: {
    project_id: meta.project_id,
    report_type: meta.report_type,
    evidence_hash: meta.evidence_hash,
    json_output: {
      report_type: meta.report_type,
      generated_at: new Date().toISOString(),
      evidence_hash: meta.evidence_hash,
      indexed_docs_count: meta.indexed_docs_count,
      sections: sections,
      findings_count: Object.keys(sections).length
    }
  }
}];

const items = $input.all();
const item = items[0].json;
const meta = $('Build Evidence Hash').first().json;

const isCacheHit = item.source === 'cache';

return [{
  json: {
    status: isCacheHit ? 'cache_hit' : 'generated',
    project_id: meta.project_id,
    report_type: meta.report_type,
    evidence_hash: meta.evidence_hash,
    html_content: item.html_content || '',
    md_content: item.md_content || '',
    json_output: item.json_output || {},
    completed_at: new Date().toISOString()
  }
}];
